apiVersion: apps/v1
kind: StatefulSet
metadata:
  name: {{sts_name}}
  namespace: {{namespace}}
spec:
  serviceName: {{sts_name}}
  replicas: {{replicas}}
  selector:
    matchLabels:
      app: {{sts_name}}
  template:
    metadata:
      labels:
        app: {{sts_name}}
    spec:
      containers:
        - name: {{sts_name}}
          image: {{image}}
          ports:
            - containerPort: {{container_port}}
          volumeMounts:
            - name: data
              mountPath: /var/lib/data
  volumeClaimTemplates:
    - metadata:
        name: data
      spec:
        accessModes: ["ReadWriteOnce"]
        storageClassName: {{storage_class}}
        resources:
          requests:
            storage: {{storage_size}}
